(* [comment removed for export] *)
Lemma PBODY My modely LKy Awy cry (y : PM.vstr) (gy : Z) (fx5 : FPState) R5 (j : Z) (bsy : list Z) (nd : Z) :
  GM (PM.vs_own y) My modely LKy Awy cry -> kstr_at My o y -> kcontent My o y bsy -> DGF nd My -> nd <= 24 -> PQMA.ks_ok SM y gy -> PM.vs_size y < SM ->
  PMSP.credit_le (PMSPA.scA L (PQMA.pot_ks (PMSPA.HV L ar) SM y gy)) cry ->
  REGSP R5 -> getr R5 (reg 22) = Z_to_bv 64 (F + 32 + j) -> getr R5 (reg 26) = Z_to_bv 64 (F + 32 + j) ->
  L5KA.zeros_at My (F / 8 + 2147450880 + 4) 3 -> 0 <= j <= 19 -> j < nd ->
  (forall (fx6 : FPState) R6 M6 model6 LK6 Aw6 (y' : PM.vstr) (gy' : Z) cr6 (c : Z),
      GM (PM.vs_own y') M6 model6 LK6 Aw6 cr6 -> kstr_at M6 o y' -> kcontent M6 o y' (bsy ++ [c]) -> 48 <= c <= 57 -> DGF nd M6 -> PQMA.ks_ok SM y' gy' -> PM.vs_size y' = PM.vs_size y + 1 ->
      PMSP.credit_keep cry cr6 (PMSPA.scA L (PQMA.pot_ks (PMSPA.HV L ar) SM y gy)) (PMSPA.scA L (PQMA.pot_ks (PMSPA.HV L ar) SM y' gy')) ->
      REGSP R6 -> getr R6 (reg 22) = Z_to_bv 64 (F + 32 + j) -> getr R6 (reg 26) = Z_to_bv 64 (F + 32 + j) -> L5KA.zeros_at M6 (F / 8 + 2147450880 + 4) 3 ->
      srealizes RSEGS SCFG (@PMSP.cfg RSEGS fx6 R6 RA_PB M6 model6) K) ->
