(* [comment removed for export] *)
Lemma DLOOPP (f : nat) : forall (fx : FPState) (Rd : bvmap 5 word) (Mv : mem) (k xx : Z),
  getr Rd (reg 2) = Z_to_bv 64 spc -> getr Rd (reg 10) = Z_to_bv 64 M10 -> getr Rd (reg 11) = Z_to_bv 64 10 -> getr Rd (reg 12) = Z_to_bv 64 254 ->
  getr Rd (reg 13) = Z_to_bv 64 xx -> getr Rd (reg 21) = Z_to_bv 64 k -> getr Rd (reg 22) = Z_to_bv 64 v -> getr Rd (reg 25) = Z_to_bv 64 (F + 32) ->
  7036928 <= F <= 140737488354816 -> F mod 32 = 0 -> (2147446784 + 17592186048512 <= F \/ F + 512 <= 2147446784) ->
  L5.writable RSEGS Mv (F + 32) 24 ->
  0 <= xx < 2 ^ 64 -> 0 <= k -> Z.of_nat f = 20 - k -> k + PQVA.ndig_f f xx <= 20 -> v <= 2 ^ 63 - 1 ->
  exists (fx' : FPState) R' Mv', msteps RSEGS (st fx Rd POSL Mv) (st fx' R' QB Mv') /\ mem_grows Mv Mv'
    /\ (forall a, 0 <= a < 2 ^ 64 -> ~ (F + 32 + k <= a < F + 32 + (k + PQVA.ndig_f f xx)) -> Mv' (Z_to_bv 64 a) = Mv (Z_to_bv 64 a))
    /\ getr R' (reg 21) = Z_to_bv 64 (k + PQVA.ndig_f f xx)
    /\ getr R' (reg 22) = Z_to_bv 64 (F + 32 + (k + PQVA.ndig_f f xx - 1)) /\ getr R' (reg 26) = Z_to_bv 64 (F + 32 + (k + PQVA.ndig_f f xx - 1))
    /\ getr R' (reg 27) = Z_to_bv 64 (F + 32 + (k + PQVA.ndig_f f xx))
    /\ (forall i, In i KDP -> getr R' (reg i) = getr Rd (reg i))
