(* [comment removed for export] *)
(* [comment removed for export] *)
Lemma SDIVRUN (fx : FPState) (Rn : bvmap 5 word) (Mv : mem) (a k : Z) :
  getr Rn (reg 15) = Z_to_bv 64 (2 ^ 64 - a) -> getr Rn (reg 10) = Z_to_bv 64 MS -> getr Rn (reg 21) = Z_to_bv 64 k ->
  1 <= a <= 2 ^ 63 -> 0 <= k < 2 ^ 32 ->
  exists Rn', msteps RSEGS (st fx Rn 0xba378 Mv) (st fx Rn' 0xba38c Mv)
    /\ getr Rn' (reg 15) = Z_to_bv 64 (- (a / 10)) /\ getr Rn' (reg 21) = Z_to_bv 64 (k + 1) /\ getr Rn' (reg 5) = Z_to_bv 64 1
