(* [comment removed for export] *)
(* [comment removed for export] *)
Lemma DLOOPN (f : nat) : forall (fx : FPState) (Rd : bvmap 5 word) (Mv : mem) (k a : Z),
  getr Rd (reg 2) = Z_to_bv 64 spc -> getr Rd (reg 10) = Z_to_bv 64 MS -> getr Rd (reg 11) = Z_to_bv 64 10 -> getr Rd (reg 12) = Z_to_bv 64 18446744073709551596 ->
  getr Rd (reg 13) = Z_to_bv 64 254 -> getr Rd (reg 15) = Z_to_bv 64 (2 ^ 64 - a) -> getr Rd (reg 20) = Z_to_bv 64 o -> getr Rd (reg 21) = Z_to_bv 64 k ->
  getr Rd (reg 22) = Z_to_bv 64 v -> getr Rd (reg 25) = Z_to_bv 64 (F + 32) ->
  7036928 <= F <= 140737488354816 -> F mod 32 = 0 -> (2147446784 + 17592186048512 <= F \/ F + 512 <= 2147446784) ->
  L5.writable RSEGS Mv (F + 32) 24 ->
  1 <= a <= 2 ^ 63 -> 0 <= k -> Z.of_nat f = 20 - k -> k + PQVA.ndig_f f a <= 20 -> 2 ^ 63 <= v < 2 ^ 64 ->
  exists (fx' : FPState) R' Mv', msteps RSEGS (st fx Rd NEGL Mv) (st fx' R' PBPC Mv') /\ mem_grows Mv Mv'
    /\ (forall aa, 0 <= aa < 2 ^ 64 -> ~ (F + 32 + k <= aa < F + 32 + (k + PQVA.ndig_f f a)) -> Mv' (Z_to_bv 64 aa) = Mv (Z_to_bv 64 aa))
    /\ getr R' (reg 1) = Z_to_bv 64 RA_PBS /\ getr R' (reg 10) = Z_to_bv 64 o /\ getr R' (reg 11) = Z_to_bv 64 45
    /\ getr R' (reg 21) = Z_to_bv 64 (k + PQVA.ndig_f f a) /\ getr R' (reg 27) = Z_to_bv 64 (F + 32 + (k + PQVA.ndig_f f a))
    /\ (forall i, In i KDN -> getr R' (reg i) = getr Rd (reg i))
