Definition srcB (M : word -> option byte) : Prop := PQASA.src_okA RSEGS L HI M LB FF qs n /\ L5.bytes_at RSEGS M qs sbs.
Hypothesis SRC0 : srcB M0.
Hypothesis SLEN : Z.of_nat (length sbs) = n.
Hypothesis SBOK : NEM.bytes_ok sbs.
Hypothesis APT : qs + n <= o \/ o + 24 <= qs.
Hypothesis KS0 : kstr_at M0 o x.
Hypothesis KC0 : kcontent M0 o x kbs.
Hypothesis KO0 : PQMA.ks_ok SM x g.
Hypothesis HSM : SM <= PQASA.SMMAX.
Hypothesis CR0 : PMSP.credit_le (scA (PQMA.pot_ks HV SM x g)) cr0.
Hypothesis KONT : forall (fx' : FPState) (R' : bvmap 5 word) (M' : word -> option byte) (model' : Model) (LK' : list fframe) (Aw' : list (Z * Z)) (x' : PM.vstr) (g' : Z) (cr' : credit),
  regs_preserved R0 R' -> kstr_at M' o x' -> kcontent M' o x' (kbs ++ sbs) -> PQMA.ks_ok SM x' g' -> PM.vs_size x' = PM.vs_size x + n ->
  (PM.vs_size x + n <= PM.vs_cap x -> PM.vs_own x' = PM.vs_own x /\ g' = g) ->
  L5CA.ahpres L ar LB FF S PQAKZ3.SC_SCR [(o, 24)] M0 M' ->
  PMSP.credit_keep cr0 cr' (scA (PQMA.pot_ks HV SM x g)) (scA (PQMA.pot_ks HV SM x' g')) ->
  model_rt model0 model' -> incl LK' LK0 -> incl Aw0 Aw' -> L5CA.amodel_ok Aw' model' ->
  ri_inv HI (PM.vs_own x' ++ LB) FF LK' cr' Aw' M' (vml_of model') ->
  srealizes RSEGS SCFG (@PMSPA.cfg RSEGS fx' R' r M' model') K.
Let need : Z := PM.vs_size x + n.
Let GA : Z := PQASA.gcount (PM.vs_cap x) need.

