Lemma move (fx : FPState) R M model LK Aw (x' : PM.vstr) (g' : Z) (cr' : credit) :
  stok model LK Aw -> kstr_at M o x' -> L5.bytes_at RSEGS M (PM.vs_data o x') kbs -> PQMA.ks_ok SM x' g' -> PM.vs_size x' = need ->
  (need <= PM.vs_cap x -> PM.vs_own x' = PM.vs_own x /\ g' = g) ->
  PMSP.credit_keep cr0 cr' (scA (PQMA.pot_ks HV SM x g)) (scA (PQMA.pot_ks HV SM x' g')) ->
  getr R (reg 1) = Z_to_bv 64 0xbe8b8 -> getr R (reg 2) = Z_to_bv 64 (S - 80) -> getr R (reg 4) = Z_to_bv 64 (hl_tp L) -> getr R (reg 8) = Z_to_bv 64 (PM.vs_size x) ->
  getr R (reg 9) = Z_to_bv 64 o -> getr R (reg 10) = Z_to_bv 64 (PM.vs_data o x' + PM.vs_size x) -> getr R (reg 11) = Z_to_bv 64 qs -> getr R (reg 12) = Z_to_bv 64 n ->
  getr R (reg 22) = Z_to_bv 64 2147450880 -> getr R (reg 23) = Z_to_bv 64 (o / 8 + 2147450880) -> getr R (reg 24) = Z_to_bv 64 (PM.vs_data o x') ->
  kept0 R -> saves M -> mem_ok M -> srcB M ->
  ri_inv HI (PM.vs_own x' ++ LB) FF LK cr' Aw M (vml_of model) ->
  srealizes RSEGS SCFG (@PMSPA.cfg RSEGS fx R 0x7f298 M model) K.
