Lemma SLOT M4 model4 LK4 Aw4 s4 sm4 e4 cr4 (fx4 : FPState) R4 len gsb :
  MM M4 model4 LK4 Aw4 s4 sa sm4 e4 cr4 eb -> REGS R4 ->
  getr R4 (reg 19) = Z_to_bv 64 (op + 8) -> getr R4 (reg 21) = Z_to_bv 64 (((op + 8) / 8) + 2147450880) ->
