(* [comment removed for export] *)
Lemma stepC w40 w48 v byo raC (fxq : FPState) Rq Mq mdq LKq Awq crq kq : runC v byo raC -> (byo = -50 \/ byo = -49) -> L5.ra_ok raC ->
  CINV w40 w48 Mq mdq LKq Awq crq kq 0 0 -> inregs Rq sp ov -> csk Rq -> getr Rq (reg 10) = Z_to_bv 64 osk -> getr Rq (reg 11) = Z_to_bv 64 v ->
  (forall (fx2 : FPState) R2 M2 md2 LK2 Aw2 cr2 k2, CINV w40 w48 M2 md2 LK2 Aw2 cr2 k2 1 1 -> inregs R2 sp ov -> csk R2 ->
      srealizes RSEGS SCFG (PMSPA.cfg RSEGS (fx:=fx2) R2 raC M2 md2) K) ->
