Theorem parser_ctor_of_push : PMA.locale_ctor_spec L ar HI -> PMA.opnew_spec L ar HI -> PQSAXQ.push_root_spec RSEGS PMA.AD L ar HI 0xcf178 ->
  PQRAa.parser_ctor_spec L ar HI.
Proof.
  intros LOC NEW PSH. apply (PQAPCSG.spec_of L ar HI).
  intros fx R M model K LB FF LK Aw cr sp r fb oo PRE KT.
  apply (PQAPC1.head L ar C IL HI LY HIok ICok ILY LOC fx R M model K LB FF LK Aw cr sp r fb oo PRE).
  intros fx1 R1 M1 model1 LK1 Aw1 MID1.
  apply (PQAPC2.memsets L ar C IL HI LY HIok ICok ILY fx1 R M model K LB FF LK Aw cr sp r fb oo R1 M1 model1 LK1 Aw1 PRE MID1).
  intros fx2 R2 M2 model2 LK2 Aw2 MID2.
  exact (PQAPC3.tail L ar C IL HI LY HIok ICok ILY NEW PSH fx2 R M model K LB FF LK Aw cr sp r fb oo R2 M2 model2 LK2 Aw2 PRE MID2 KT).
